import {
    BlockTypeSelect, BoldItalicUnderlineToggles, CreateLink, InsertCodeBlock, InsertImage, InsertTable,
    InsertThematicBreak, ListsToggle, Separator, UndoRedo,
} from '@mdxeditor/editor'
import type { ReactNode } from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { MarkdownListIndentToolbarControls } from './markdown_list_indent_toolbar_controls'
import { MarkdownLocalTextSearchToolbarControl } from './markdown_local_text_search_toolbar_control'
import { MarkdownPlaceholderToolbarControl } from './markdown_placeholder_toolbar_control'

interface MarkdownFormatToolbarControlsProps {
    endControls?: ReactNode
    overlayContainer?: HTMLElement | null
    placeholders?: readonly ActionPlaceholder[]
    readOnly?: boolean
    undoRedoControls?: ReactNode
}

/** The full formatting command set supported by the shared markdown editor. */
export function MarkdownFormatToolbarControls(props: MarkdownFormatToolbarControlsProps = {}) {
    const { endControls, overlayContainer, placeholders = [], readOnly = false, undoRedoControls } = props

    return (
        <>
            {!readOnly ? (
                <>
                    {undoRedoControls ?? <UndoRedo />}
                    <Separator />
                    <BoldItalicUnderlineToggles />
                    <Separator />
                    <ListsToggle />
                    <MarkdownListIndentToolbarControls />
                    <BlockTypeSelect />
                    <Separator />
                    <CreateLink />
                    <InsertImage />
                    <Separator />
                    <InsertTable />
                    <InsertThematicBreak />
                    <InsertCodeBlock />
                    <Separator />
                </>
            ) : null}
            <MarkdownLocalTextSearchToolbarControl />
            {!readOnly && placeholders.length > 0 ? (
                <>
                    <Separator />
                    <MarkdownPlaceholderToolbarControl overlayContainer={overlayContainer} placeholders={placeholders} />
                </>
            ) : null}
            {endControls}
        </>
    )
}

it('renders read-only when requested', () => {
    render(
        <AppThemeProvider>
            <MarkdownEditor markdown="locked" onChange={vi.fn()} readOnly />
        </AppThemeProvider>,
    )

    expect(screen.getByRole('textbox')).toHaveAttribute('readonly')
})

it('does not infer read-only state from an empty data-source binding', () => {
    render(
        <AppThemeProvider>
            <MarkdownEditor
                binding="list-card"
                dataSource={new TestMarkdownDataSource()}
                historyStore={new MarkdownDocumentHistoryStore()}
            />
        </AppThemeProvider>,
    )

    expect(screen.getByRole('textbox')).not.toHaveAttribute('readonly')
})

it('shows placeholder insertion only when placeholders are configured', () => {
    const view = render(
        <AppThemeProvider>
            <MarkdownEditor markdown="" onChange={vi.fn()} placeholders={ACTION_PROMPT_PLACEHOLDERS} />
        </AppThemeProvider>,
    )

    expect(screen.getByRole('button', { name: 'Insert placeholder' })).toBeInTheDocument()

    view.rerender(
        <AppThemeProvider>
            <MarkdownEditor markdown="" onChange={vi.fn()} />
        </AppThemeProvider>,
    )

    expect(screen.queryByRole('button', { name: 'Insert placeholder' })).not.toBeInTheDocument()
})

it('uses the MDXEditor palette matching the app theme', () => {
    window.localStorage.setItem(THEME_MODE_STORAGE_KEY, 'dark')

    renderEditor()

    expect(screen.getByTestId('mdx-editor')).toHaveClass('dark-theme')
})

